StructuredText.Text:
#tempOpen := 0;
#tempClosed := 0;
#tempTransit := 0;
#tempFault := 0;
#tempLocal := 0;
#tempConfigured := 0;
#tempAftUnh := 0;   #tempMidUnh := 0;   #tempFwdUnh := 0;
#tempErOpen := 0;    #tempErClosed := 0;    #tempErTransit := 0;    #tempErFault := 0;    #tempErLocal := 0;    #tempErConfigured := 0;
#tempFwdOpen := 0;   #tempFwdClosed := 0;   #tempFwdTransit := 0;   #tempFwdFault := 0;   #tempFwdLocal := 0;   #tempFwdConfigured := 0;
#tempAftOpen := 0;   #tempAftClosed := 0;   #tempAftTransit := 0;   #tempAftFault := 0;   #tempAftLocal := 0;   #tempAftConfigured := 0;

        // Flash clocks — TIME based, not scan-count based.
// The old version incremented a counter and toggled at >= 10, i.e. every TEN SCANS. That is
// only 1 Hz if a scan takes 50 ms; the real scan is a few milliseconds, so it was toggling at
// roughly 16 Hz and the popup's "1 Hz" fault flash was actually a fast flicker. A TON runs on
// the CPU clock, so these are correct regardless of scan time.
"Valves_DB".ClockCounter := 0;   // legacy scan counter, no longer used
"Valves_DB".Clk1Tmr(IN := TRUE, PT := T#500MS);
IF "Valves_DB".Clk1Tmr.Q THEN
    "Valves_DB".Clock_1Hz := NOT "Valves_DB".Clock_1Hz;   // a genuine 1 Hz now
    "Valves_DB".Clk1Tmr(IN := FALSE, PT := T#500MS);   // reset NOW, same scan
END_IF;
"Valves_DB".FlashTmr(IN := TRUE, PT := T#2S);
IF "Valves_DB".FlashTmr.Q THEN
    "Valves_DB".Clock_Flash := NOT "Valves_DB".Clock_Flash;   // 0.25 Hz: 2 s on, 2 s off
    "Valves_DB".FlashTmr(IN := FALSE, PT := T#2S);   // reset NOW, same scan
END_IF;
// Self-referencing IN (IN := NOT Q) looked correct but never produced an observable
// pulse: the moment the TON sets Q, the IN expression evaluates FALSE and the timer
// clears Q again before the following IF can read it. Observed live 2026-08-19 -
// Clock_Flash never went true (faulted valves showed steady position colour, no red
// flash) and the table windows only ever refreshed when a page button was pressed.
// Drive IN unconditionally TRUE and reset explicitly in the same scan instead.
"Valves_DB".WinTmr(IN := TRUE, PT := T#200MS);
#winTick := "Valves_DB".WinTmr.Q;   // latch before the reset clears it
IF #winTick THEN
    "Valves_DB".WinTmr(IN := FALSE, PT := T#200MS);
END_IF;

// Hardware health starts healthy-until-told-otherwise, once per CPU start.
//
// This used to test "HwHealthy[1] AND [8] are both FALSE" as a stand-in for "nothing has been
// set yet". That worked only while nothing drove those two bits - and they are bit 0 (PLC CPU
// fault) and bit 7 (HMI heartbeat loss), both of which are due to be driven. The moment they
// are, the sentinel becomes reachable in normal operation: one CPU fault alongside a lost
// heartbeat would re-run this loop and reset all nine bits to healthy, silently taking the
// three WORKING station alarms with it. Not a far-fetched pair either - a panel powered down
// overnight holds heartbeat-lost on its own, so it needs only one CPU diagnostic beside it.
//
// HwInitDone says what is actually meant. It is NonRetain with no start value, so it is FALSE
// on every CPU start and TRUE for the rest of that run - which is the real definition of
// "first scan", and cannot be re-entered by live fault data no matter what drives the bits.
// Keep it NonRetain even as other Valves_DB members become retentive: resetting on every
// restart is the whole point of it.
IF NOT "Valves_DB".HwInitDone THEN
    FOR #b := 1 TO 9 DO
        "Valves_DB".HwHealthy[#b] := TRUE;
    END_FOR;

    // Restore which valves were in service, from the retentive mirror. Without this the
    // whole plant came back UNCONFIGURED after any power cut: Configured is non-retentive
    // with no start value, so all 89 read FALSE, FC_IoMapper skipped every valve and
    // FB_ValveLoop refused every command - while the panel looked entirely normal. Nothing
    // on the ship answered until somebody knew to press CONFIGURE ALL.
    //
    // Restored here rather than anywhere else because this block is the only code that runs
    // exactly once per CPU start, before the 1..89 loop below saves the value straight back.
    // Order matters: restore first, then the loop's save is a no-op on this scan.
    FOR #b := 1 TO 89 DO
        "Valves_DB".Valve[#b].Configured := "Valves_DB".ConfiguredRet[#b];
    END_FOR;

    "Valves_DB".HwInitDone := TRUE;
END_IF;

// Remote I/O station health, from OB86 (RackOrStationFailure) via Diag_DB. HwHealthy[2..4]
// are already wired to the System_Aft/Bilge/Fwd_RIO_Fault alarms through HwWord bits 1..3 -
// those alarms have existed since the alarm set was generated and nothing has ever set them,
// so a station could drop off PROFINET and the alarm built for exactly that stayed silent.
//
// Derived here every scan rather than written directly by OB86, because of the auto-init
// immediately above: it fires whenever HwHealthy[1] and [8] are both FALSE, which is the
// state at CPU startup. A station already down when the CPU starts would have OB86 set its
// bit and then have that init wipe it in the same scan. Diag_DB is written by OB86 alone and
// read here, so the ordering cannot lose a genuine station loss.
//
// Sense is inverted: HwHealthy TRUE means well, and HwWord sets its bit on NOT HwHealthy.
"Valves_DB".HwHealthy[2] := NOT "Diag_DB".AftLost;
"Valves_DB".HwHealthy[3] := NOT "Diag_DB".MidLost;
"Valves_DB".HwHealthy[4] := NOT "Diag_DB".FwdLost;

FOR #i := 1 TO 89 DO
    // Keep the retentive mirror in step with the live flag, so whatever an engineer sets on
    // the Config screen survives the next blackout. One Bool copy per valve per scan.
    "Valves_DB".ConfiguredRet[#i] := "Valves_DB".Valve[#i].Configured;

    // Count configured-but-unhealthy valves per station, for the 24 V group-fault detection
    // after this loop. Free here - the loop already runs 1..89 every scan.
    IF "Valves_DB".Valve[#i].Configured AND NOT "Valves_DB".Valve[#i].Healthy THEN
        IF #i <= 27 THEN
            #tempAftUnh := #tempAftUnh + 1;
        ELSIF #i <= 54 THEN
            #tempMidUnh := #tempMidUnh + 1;
        ELSE
            #tempFwdUnh := #tempFwdUnh + 1;
        END_IF;
    END_IF;

    // Is this valve's station currently in a supply fault? Uses last scan's flag, which is
    // set after this loop - one scan of lag against a 2 s debounce, so it does not matter.
    #supp := (#i <= 27 AND "Valves_DB".AftSupplyFault)
          OR (#i > 27 AND #i <= 54 AND "Valves_DB".MidSupplyFault)
          OR (#i > 54 AND "Valves_DB".FwdSupplyFault);

    // Per-valve stroke times, replacing the compiled-in T#8S and T#5S. Both were simulation
    // numbers: real DN200-DN400 hydraulic valves stroke in 15-60s, and because the command is
    // MAINTAINED, an expiring timer drops the run latch and physically halts the valve rather
    // than merely raising an alarm. The 5s direction grace was the worse of the two, since it
    // arms the moment a valve is driven while still on its starting limit switch - which is
    // exactly what a large valve does for its first few seconds - so every normal stroke
    // raised a direction fault before the travel timeout ever got a chance.
    //
    // Zero guard is not paranoia: PT := T#0S expires on the very first scan, so a bad import
    // or a mis-typed panel entry would be worse than the 8 seconds this replaces. Falling back
    // to the generous default keeps a wrong number merely late rather than actively harmful.
    #travelPT := "Valve_Channels_DB".TravelTimeout[#i];
    IF #travelPT <= T#0S THEN #travelPT := T#60S; END_IF;
    #seatPT := "Valve_Channels_DB".SeatBreakGrace[#i];
    IF #seatPT <= T#0S THEN #seatPT := T#10S; END_IF;

    IF "Valves_DB".Valve[#i].Configured THEN
        // Snapshot BEFORE this scan's command/timer processing runs — needed by the
        // Unexpected Movement (F) guard below to tell a genuine idle-and-unexplained drop
        // apart from a normal command-triggered one (a fresh command sets SimStep 0->nonzero
        // in section 1; a completing travel sets it nonzero->0 in section 2 — comparing
        // only the post-scan value can't distinguish either from true idle-the-whole-scan).
        #simStepAtStart := #SimStep[#i];

        // Auto-initialize Healthy status to TRUE and Resting Position to CLOSED seat — but
        // ONLY the first scan a valve is ever seen, via the Initialized latch. Simulation-only
        // scaffolding (see the Initialized member's comment in Valves_DB): without this
        // one-time gate, this ran every scan and silently reset ClosedFB back to TRUE any time
        // a valve was idle with both feedbacks false — which is exactly the state Loss of
        // Position (E) needs to sustain for 2s to fire, so E could never actually trigger.
        //
        // Real-channel valves must NEVER have ClosedFB assumed here - only real hardware
        // feedback (via FC_IoMapper) may ever set it. Confirmed live via watch-table test
        // 2026-08-13: forcing a real valve's Configured=TRUE while its real DI already read
        // OpenFB=TRUE caused this block to also force ClosedFB=TRUE the same scan (assuming
        // "starts closed"), so both feedbacks were true at once and the double-indication
        // fault check below correctly tripped Healthy=FALSE for the wrong reason. Real valves
        // still get the one-time Healthy=TRUE start, just never the assumed position.
        IF NOT "Valves_DB".Initialized[#i] THEN
            "Valves_DB".Initialized[#i] := TRUE;
            // Real-channel valves get NOTHING seeded here. Healthy, OpenFB and ClosedFB are
            // valve-owned signals - the valve reports them, the PLC only reads them - and
            // FC_IoMapper fills all three from real hardware later in this very same scan.
            // Seeding Healthy:=TRUE was harmless in effect (overwritten immediately) but it
            // was still the PLC writing a signal it does not own. Removed 2026-08-15.
            IF "Valve_Channels_DB".OpenFbChannel[#i] = 0
               AND NOT "Valves_DB".Valve[#i].OpenFB AND NOT "Valves_DB".Valve[#i].ClosedFB
               AND #SimStep[#i] = 0 THEN
                "Valves_DB".Valve[#i].Healthy := TRUE;
                "Valves_DB".Valve[#i].ClosedFB := TRUE;
            END_IF;
        END_IF;

        // 1. Failsafe Command, real-channel latch, and Motion Simulation
        // A valve with a real DI channel assigned (Valve_Channels_DB.OpenFbChannel[i] > 0)
        // never gets its OpenFB/ClosedFB touched here or in Section 2 below - those come from
        // real hardware via FC_IoMapper instead. What THIS valve needs from a command is a
        // sustained "run" output (OpenValve/CloseValve) for FC_IoMapper to drive to the real
        // DQ, latched until the real limit switch confirms arrival (see the block right after
        // this one) or a timeout gives up (Section 2, real-valve branch).
        IF NOT "Valves_DB".Valve[#i].LocalMode AND "Valves_DB".Valve[#i].Healthy THEN
            // Interlock: Ignore if both commands pressed simultaneously
            IF "Valves_DB".Valve[#i].OpenCmd AND "Valves_DB".Valve[#i].CloseCmd THEN
                "Valves_DB".Valve[#i].OpenCmd := FALSE;
                "Valves_DB".Valve[#i].CloseCmd := FALSE;
            ELSIF "Valves_DB".Valve[#i].OpenCmd THEN
                // Record the operator's intent before acting on it. Never cleared on arrival -
                // this is what the HMI compares against actual position to spot a valve that is
                // not where it was told to go (stuck limit switch, failed actuator).
                "Valves_DB".CmdPos[#i] := 1;   // 1 = OPEN
                IF "Valve_Channels_DB".OpenFbChannel[#i] > 0 THEN
                    "Valves_DB".Valve[#i].OpenValve := TRUE;
                    "Valves_DB".Valve[#i].CloseValve := FALSE;
                ELSE
                    // Start OPENING sequence: Immediately leave seat -> MOVING!
                    "Valves_DB".Valve[#i].OpenFB := FALSE;
                    "Valves_DB".Valve[#i].ClosedFB := FALSE;
                    #SimStep[#i] := 1; // 1 = opening in progress
                END_IF;
                "Valves_DB".Valve[#i].OpenCmd := FALSE;
                "Valves_DB".Valve[#i].CloseCmd := FALSE;
            ELSIF "Valves_DB".Valve[#i].CloseCmd THEN
                "Valves_DB".CmdPos[#i] := 2;   // 2 = CLOSE
                IF "Valve_Channels_DB".OpenFbChannel[#i] > 0 THEN
                    "Valves_DB".Valve[#i].CloseValve := TRUE;
                    "Valves_DB".Valve[#i].OpenValve := FALSE;
                ELSE
                    // Start CLOSING sequence: Immediately leave seat -> MOVING!
                    "Valves_DB".Valve[#i].OpenFB := FALSE;
                    "Valves_DB".Valve[#i].ClosedFB := FALSE;
                    #SimStep[#i] := 2; // 2 = closing in progress
                END_IF;
                "Valves_DB".Valve[#i].CloseCmd := FALSE;
                "Valves_DB".Valve[#i].OpenCmd := FALSE;
            END_IF;
        ELSE
            // LOCAL MODE / UNHEALTHY: discard any pending command outright.
            // Without this the command bit stayed latched while it was being (correctly)
            // refused, and then executed by itself on the very next scan after the valve
            // returned to remote/healthy - i.e. the valve moves with nobody commanding it,
            // seconds or hours after the button was pressed. Found by live test 2026-08-15
            // (CM79: OPEN pressed in Local, LocalMode cleared, valve immediately ran and
            // then latched Fail-to-Open). A refused command must be forgotten, not queued.
            "Valves_DB".Valve[#i].OpenCmd := FALSE;
            "Valves_DB".Valve[#i].CloseCmd := FALSE;
        END_IF;

        // Real valves only: drop the run-latch the instant the real limit switch (read
        // elsewhere by FC_IoMapper) confirms arrival, and force it off on an unhealthy/local
        // transition so a stale "still running" output can't linger past a fault.
        IF "Valve_Channels_DB".OpenFbChannel[#i] > 0 THEN
            IF "Valves_DB".Valve[#i].OpenFB THEN "Valves_DB".Valve[#i].OpenValve := FALSE; END_IF;
            IF "Valves_DB".Valve[#i].ClosedFB THEN "Valves_DB".Valve[#i].CloseValve := FALSE; END_IF;
            IF "Valves_DB".Valve[#i].LocalMode OR NOT "Valves_DB".Valve[#i].Healthy THEN
                "Valves_DB".Valve[#i].OpenValve := FALSE;
                "Valves_DB".Valve[#i].CloseValve := FALSE;
            END_IF;
        END_IF;

        // 1a. Travel timeouts are self-clearing on successful arrival. A latched Fail-to-Open
        // sitting on a valve that has since opened correctly is actively misleading: the panel
        // shows FAULT on a working valve, and the operator cannot tell "broken now" from "broke
        // once, fine since". Clearing on arrival lets the alarm show raised -> cleared; it stays
        // in alarm history and still needs acknowledging, so the record survives.
        // Only the travel timeouts behave this way. UnexpMove stays latched (it is an event that
        // happened, with no natural "resolved" state) and DirFault stays latched (it points at
        // wiring, which does not fix itself and should need a deliberate human reset).
        // Note the asymmetry is deliberate: arriving OPEN clears only the open timeout. A failed
        // close leaves the valve at the open limit, so ClosedFB is false and TimeoutCloseAlarm
        // correctly survives.
        IF "Valves_DB".Valve[#i].OpenFB THEN
            "Valves_DB".TimeoutOpenAlarm[#i] := FALSE;
        END_IF;
        IF "Valves_DB".Valve[#i].ClosedFB THEN
            "Valves_DB".TimeoutCloseAlarm[#i] := FALSE;
        END_IF;

        // 1b. Direction / limit-switch discrepancy (H) — the physical evidence contradicts the
        // command. Driving OPEN with the CLOSED limit still made (or the mirror) after the 5s
        // grace means either the valve went the wrong way (OPEN/CLOSE swapped at the interposing
        // relays) or it never left its seat (dead actuator, stuck limit switch). The PLC cannot
        // separate those from two limit switches, and it must not try: deducing "the wiring
        // looks swapped so I will drive the other output" would bake compensation for a wiring
        // fault into safety logic, and every valve would invert the day someone fixed the wiring.
        // So: stop driving, latch, and let a human look at it.
        // The IN condition self-resets the timer the moment the contradiction clears, so a
        // normal stroke leaving its seat within the grace never arms this.
        "Valves_DB".DirTmr[#i](
            IN := ("Valves_DB".Valve[#i].OpenValve AND "Valves_DB".Valve[#i].ClosedFB)
                  OR ("Valves_DB".Valve[#i].CloseValve AND "Valves_DB".Valve[#i].OpenFB),
            PT := #seatPT);
        IF "Valves_DB".DirTmr[#i].Q THEN
            "Valves_DB".DirFault[#i] := TRUE;
            // Fail safe: when direction is in doubt, stop. Continuing to energise would keep
            // opening a valve somebody asked to close.
            "Valves_DB".Valve[#i].OpenValve := FALSE;
            "Valves_DB".Valve[#i].CloseValve := FALSE;
        END_IF;

        // 2. Motion Delay Execution — real 3.0s TON per valve (Valve[i].TimerOpen/Close
        // are dedicated instances since they live inside this array element). Scan-cycle
        // counting was used before; it only equalled 3.0s if every scan took exactly
        // 100ms, which isn't guaranteed, so the MOVING state could flash by in well
        // under a second on a fast scan. A TON runs on the CPU's real-time clock, so
        // this duration is exact regardless of scan speed.
        // Stuck (set via the popup's SIMULATE STUCK toggle) holds the valve at the normal
        // 3s completion so it never arrives — TON.ET keeps counting past PT as long as IN
        // stays true, so at 8s (well past the normal 3s travel) that's a genuine failure to
        // arrive, not just "still moving": latch Fail to Open/Close (C/D) and give up on the
        // sequence, leaving both feedbacks false (position genuinely unknown).
        // IN covers both cases: SimStep=1 during a simulated open travel, OpenValve latched
        // true during a real one - the two are mutually exclusive per valve (Section 1 only
        // ever sets one or the other for a given i), so sharing the one TON instance is safe.
        "Valves_DB".Valve[#i].TimerOpen(IN := (#SimStep[#i] = 1) OR "Valves_DB".Valve[#i].OpenValve, PT := #travelPT);
        IF #SimStep[#i] = 1 THEN
            IF NOT "Valves_DB".Stuck[#i] AND "Valves_DB".Valve[#i].TimerOpen.ET >= T#3S THEN
                "Valves_DB".Valve[#i].OpenFB := TRUE;   // Reached OPEN position!
                "Valves_DB".Valve[#i].ClosedFB := FALSE;
                #SimStep[#i] := 0;                       // Sequence complete
            ELSIF "Valves_DB".Valve[#i].TimerOpen.Q THEN
                "Valves_DB".TimeoutOpenAlarm[#i] := TRUE;  // Fail to Open (C)
                "Valves_DB".Valve[#i].OpenFB := FALSE;
                "Valves_DB".Valve[#i].ClosedFB := FALSE;
                #SimStep[#i] := 0;
            END_IF;
        ELSIF "Valves_DB".Valve[#i].OpenValve AND "Valves_DB".Valve[#i].TimerOpen.Q THEN
            // Real valve commanded open 8s ago and the real limit switch never confirmed -
            // genuine failure to open. Give up on the run output; position stays whatever the
            // real feedback says (already false, or this wouldn't still be latched).
            "Valves_DB".TimeoutOpenAlarm[#i] := TRUE;  // Fail to Open (C)
            "Valves_DB".Valve[#i].OpenValve := FALSE;
        END_IF;

        "Valves_DB".Valve[#i].TimerClose(IN := (#SimStep[#i] = 2) OR "Valves_DB".Valve[#i].CloseValve, PT := #travelPT);
        IF #SimStep[#i] = 2 THEN
            IF NOT "Valves_DB".Stuck[#i] AND "Valves_DB".Valve[#i].TimerClose.ET >= T#3S THEN
                "Valves_DB".Valve[#i].ClosedFB := TRUE; // Reached CLOSED position!
                "Valves_DB".Valve[#i].OpenFB := FALSE;
                #SimStep[#i] := 0;                       // Sequence complete
            ELSIF "Valves_DB".Valve[#i].TimerClose.Q THEN
                "Valves_DB".TimeoutCloseAlarm[#i] := TRUE; // Fail to Close (D)
                "Valves_DB".Valve[#i].OpenFB := FALSE;
                "Valves_DB".Valve[#i].ClosedFB := FALSE;
                #SimStep[#i] := 0;
            END_IF;
        ELSIF "Valves_DB".Valve[#i].CloseValve AND "Valves_DB".Valve[#i].TimerClose.Q THEN
            "Valves_DB".TimeoutCloseAlarm[#i] := TRUE; // Fail to Close (D)
            "Valves_DB".Valve[#i].CloseValve := FALSE;
        END_IF;

        // 3. Failsafe Double Indication Fault Check
        IF "Valves_DB".Valve[#i].OpenFB AND "Valves_DB".Valve[#i].ClosedFB THEN
            "Valves_DB".Valve[#i].Healthy := FALSE; // Trip Fault
        END_IF;

        // 3a. Alarm conditions E (Loss of Position) and F (Unexpected Movement) — both
        // derived from the exact same OpenFB/ClosedFB pair used everywhere else; the only
        // extra ingredient is TIME and CONTEXT (was a command active, what did it say a
        // moment ago), not any new signal.
        //
        // E: idle (SimStep=0, so no travel is legitimately in progress) with NEITHER limit
        // switch made — held for 2s via PosLostTmr so a normal in-flight transition can't
        // false-trip it. Suppressed while a timeout (C/D) is already latched, since that is
        // the exact same physical symptom (no position) already alarmed under its own name.
        // NOT OpenValve/CloseValve added so a real valve mid-travel (both feedbacks
        // legitimately false while the run output is latched) doesn't false-trip this the
        // same way SimStep=0 already excludes a simulated valve mid-travel.
        "Valves_DB".PosLostTmr[#i](
            IN := (#SimStep[#i] = 0) AND NOT "Valves_DB".Valve[#i].OpenValve
                  AND NOT "Valves_DB".Valve[#i].CloseValve
                  AND NOT "Valves_DB".Valve[#i].OpenFB
                  AND NOT "Valves_DB".Valve[#i].ClosedFB
                  AND NOT "Valves_DB".TimeoutOpenAlarm[#i] AND NOT "Valves_DB".TimeoutCloseAlarm[#i],
            PT := T#2S);

        // F: a limit switch that WAS made a scan ago has dropped, with no travel sequence
        // running to explain it — nobody commanded this, so something moved the valve
        // (handwheel) or a switch/wiring fault occurred. Latched.
        // Requires SimStep to have been 0 BOTH before and after this scan's processing: a
        // fresh command (0 -> nonzero, in section 1) or a completing travel (nonzero -> 0,
        // in section 2) each only satisfy ONE side of this, so both are correctly excluded —
        // only a scan truly idle throughout can reach here.
        // Real valves: also require the run-latch off both before and after, same reasoning
        // as SimStep above - a real valve leaving its seat on a legitimate command is not
        // "unexplained" just because OpenValve/CloseValve doesn't happen to be SimStep.
        // NOT #supp: during a 24 V group fault every limit switch on the station drops at
        // once, which looks exactly like unexplained movement on all 27 valves. UnexpMove
        // is the only latched one of the three, so letting it set here would deliver the
        // whole flood the moment power came back - suppressing only the alarm bit would
        // move the flood rather than remove it.
        IF #simStepAtStart = 0 AND #SimStep[#i] = 0 AND NOT #supp
           AND NOT "Valves_DB".Valve[#i].OpenValve AND NOT "Valves_DB".Valve[#i].CloseValve THEN
            IF ("Valves_DB".PrevOpenFB[#i] AND NOT "Valves_DB".Valve[#i].OpenFB) OR
               ("Valves_DB".PrevClosedFB[#i] AND NOT "Valves_DB".Valve[#i].ClosedFB) THEN
                "Valves_DB".UnexpMove[#i] := TRUE;
            END_IF;
        END_IF;
        "Valves_DB".PrevOpenFB[#i] := "Valves_DB".Valve[#i].OpenFB;
        "Valves_DB".PrevClosedFB[#i] := "Valves_DB".Valve[#i].ClosedFB;

        // 4. Priority Summary Counting — plant-wide AND per-zone in the same pass
        // (this loop already runs 1..89 every scan regardless, so the zone-scoped
        // increments below are free — they're what let every HMI KPI/caption cell
        // read one tag instead of re-looping its zone's 28-32 valves itself).
        // Zone valve-number ranges follow physical position from stern to bow, so the HMI
        // mimic reads slots straight across: AFT=1-27, ER=28-54, FWD=55-89. Exact fit to the
        // client schedule's real 27/27/35 = 89 valves - no spare padding slots anywhere.
        #tempConfigured := #tempConfigured + 1;
        IF #i <= 27 THEN
            #tempAftConfigured := #tempAftConfigured + 1;
        ELSIF #i <= 54 THEN
            #tempErConfigured := #tempErConfigured + 1;
        ELSE
            #tempFwdConfigured := #tempFwdConfigured + 1;
        END_IF;

        // StateCode is assigned in these same branches (0=UNCONFIGURED 1=FAULT 2=LOCAL
        // 3=OPEN 4=CLOSED 5=MOVING) so the HMI reads one Int per valve instead of
        // recombining five raw bits in JavaScript on every refresh.
        // UnexpMove (F) and PosLostTmr.Q (E) added here so a valve with a genuine position
        // problem shows FAULT instead of falling through to the default MOVING bucket below,
        // which was otherwise indistinguishable from a normal in-flight transition - the exact
        // blind spot E was designed to close, but the display logic was never updated to match.
        // Position-only code — the same chain as StateCode below but WITHOUT the fault branch,
        // so a faulted valve still reports where it is. The popup shows this alongside the
        // fault rather than instead of it.
        IF "Valves_DB".Valve[#i].OpenValve THEN
            "Valves_DB".PosCode[#i] := 6;
        ELSIF "Valves_DB".Valve[#i].CloseValve THEN
            "Valves_DB".PosCode[#i] := 7;
        ELSIF "Valves_DB".Valve[#i].OpenFB AND NOT "Valves_DB".Valve[#i].ClosedFB THEN
            "Valves_DB".PosCode[#i] := 3;
        ELSIF NOT "Valves_DB".Valve[#i].OpenFB AND "Valves_DB".Valve[#i].ClosedFB THEN
            "Valves_DB".PosCode[#i] := 4;
        ELSE
            "Valves_DB".PosCode[#i] := 5;
        END_IF;

        // Fault reason, most specific first. Double indication is tested before Healthy because
        // it is what FORCES Healthy false — checking Healthy first would mask the real cause
        // behind a generic "unhealthy".
        IF "Valves_DB".Valve[#i].OpenFB AND "Valves_DB".Valve[#i].ClosedFB THEN
            "Valves_DB".FaultCode[#i] := 2;
        ELSIF "Valves_DB".DirFault[#i] THEN
            "Valves_DB".FaultCode[#i] := 7;
        ELSIF "Valves_DB".TimeoutOpenAlarm[#i] THEN
            "Valves_DB".FaultCode[#i] := 3;
        ELSIF "Valves_DB".TimeoutCloseAlarm[#i] THEN
            "Valves_DB".FaultCode[#i] := 4;
        ELSIF "Valves_DB".UnexpMove[#i] THEN
            "Valves_DB".FaultCode[#i] := 6;
        ELSIF "Valves_DB".PosLostTmr[#i].Q THEN
            "Valves_DB".FaultCode[#i] := 5;
        ELSIF NOT "Valves_DB".Valve[#i].Healthy THEN
            "Valves_DB".FaultCode[#i] := 1;
        ELSE
            "Valves_DB".FaultCode[#i] := 0;
        END_IF;

        // What the mimic box should show right now, flashing included. Computing the
        // ALTERNATION here means the HMI binds one native value map and runs no scripts at all
        // - 89 scripted boxes re-evaluating on every clock tick would be real load on the panel,
        // and this project already learned that lesson with the popup.
        // When nothing is faulted DispCode simply equals PosCode and never changes, so a healthy
        // plant produces zero tag traffic. Cost scales with faults, not with valve count.
        IF NOT "Valves_DB".Valve[#i].Configured THEN
            "Valves_DB".DispCode[#i] := 0;
        ELSIF "Valves_DB".FaultCode[#i] > 0 AND "Valves_DB".Clock_Flash THEN
            "Valves_DB".DispCode[#i] := 1;                                  // red half of the flash
        ELSIF "Valves_DB".Valve[#i].LocalMode THEN
            "Valves_DB".DispCode[#i] := 2;                                  // amber, steady
        ELSE
            "Valves_DB".DispCode[#i] := "Valves_DB".PosCode[#i];        // position
        END_IF;

        IF NOT "Valves_DB".Valve[#i].Healthy OR ("Valves_DB".Valve[#i].OpenFB AND "Valves_DB".Valve[#i].ClosedFB)
           OR "Valves_DB".TimeoutOpenAlarm[#i] OR "Valves_DB".TimeoutCloseAlarm[#i]
           OR "Valves_DB".UnexpMove[#i] OR "Valves_DB".PosLostTmr[#i].Q
           OR "Valves_DB".DirFault[#i] THEN
            "Valves_DB".StateCode[#i] := 1;
            #tempFault := #tempFault + 1;
            IF #i <= 27 THEN #tempAftFault := #tempAftFault + 1;
            ELSIF #i <= 54 THEN #tempErFault := #tempErFault + 1;
            ELSE #tempFwdFault := #tempFwdFault + 1;
            END_IF;
        ELSIF "Valves_DB".Valve[#i].LocalMode THEN
            "Valves_DB".StateCode[#i] := 2;
            #tempLocal := #tempLocal + 1;
            IF #i <= 27 THEN #tempAftLocal := #tempAftLocal + 1;
            ELSIF #i <= 54 THEN #tempErLocal := #tempErLocal + 1;
            ELSE #tempFwdLocal := #tempFwdLocal + 1;
            END_IF;
        ELSIF "Valves_DB".Valve[#i].OpenValve THEN
            // 6 = OPENING. The run latches are checked BEFORE the limit switches on purpose:
            // what the system is doing to the valve outranks where the valve currently sits.
            // Without this, a valve commanded CLOSE while still on its open limit displayed a
            // settled green "FULLY OPEN" - no acknowledgement that the command had even
            // registered on a normal stroke, and on a fault a confidently wrong indication for
            // the full travel timeout. StateCode used to answer only "where is the valve";
            // it now also answers "what is being done to it", which is the half that matters
            // when something is going wrong.
            "Valves_DB".StateCode[#i] := 6;
            #tempTransit := #tempTransit + 1;
            IF #i <= 27 THEN #tempAftTransit := #tempAftTransit + 1;
            ELSIF #i <= 54 THEN #tempErTransit := #tempErTransit + 1;
            ELSE #tempFwdTransit := #tempFwdTransit + 1;
            END_IF;
        ELSIF "Valves_DB".Valve[#i].CloseValve THEN
            "Valves_DB".StateCode[#i] := 7;   // 7 = CLOSING
            #tempTransit := #tempTransit + 1;
            IF #i <= 27 THEN #tempAftTransit := #tempAftTransit + 1;
            ELSIF #i <= 54 THEN #tempErTransit := #tempErTransit + 1;
            ELSE #tempFwdTransit := #tempFwdTransit + 1;
            END_IF;
        ELSIF "Valves_DB".Valve[#i].OpenFB AND NOT "Valves_DB".Valve[#i].ClosedFB THEN
            "Valves_DB".StateCode[#i] := 3;
            #tempOpen := #tempOpen + 1;
            IF #i <= 27 THEN #tempAftOpen := #tempAftOpen + 1;
            ELSIF #i <= 54 THEN #tempErOpen := #tempErOpen + 1;
            ELSE #tempFwdOpen := #tempFwdOpen + 1;
            END_IF;
        ELSIF NOT "Valves_DB".Valve[#i].OpenFB AND "Valves_DB".Valve[#i].ClosedFB THEN
            "Valves_DB".StateCode[#i] := 4;
            #tempClosed := #tempClosed + 1;
            IF #i <= 27 THEN #tempAftClosed := #tempAftClosed + 1;
            ELSIF #i <= 54 THEN #tempErClosed := #tempErClosed + 1;
            ELSE #tempFwdClosed := #tempFwdClosed + 1;
            END_IF;
        ELSE
            "Valves_DB".StateCode[#i] := 5;
            #tempTransit := #tempTransit + 1; // MOVING state!
            IF #i <= 27 THEN #tempAftTransit := #tempAftTransit + 1;
            ELSIF #i <= 54 THEN #tempErTransit := #tempErTransit + 1;
            ELSE #tempFwdTransit := #tempFwdTransit + 1;
            END_IF;
        END_IF;
    ELSE
        "Valves_DB".StateCode[#i] := 0;
        "Valves_DB".PosCode[#i] := 0;
        "Valves_DB".DispCode[#i] := 0;
        "Valves_DB".FaultCode[#i] := 0;
        "Valves_DB".Valve[#i].OpenCmd := FALSE;
        "Valves_DB".Valve[#i].CloseCmd := FALSE;
        // Drop the run latches too. Without this, de-configuring a valve mid-travel (the popup's
        // SERVICE toggle reaches this from the HMI) left OpenValve/CloseValve latched TRUE with
        // no logic left managing them - and since FC_IoMapper skipped unconfigured valves, the
        // DQ bit kept its last value and FC_PhysicalIoCopy went on copying it to the real %Q
        // forever. The relay would have stayed energised indefinitely while the screen showed a
        // harmless-looking UNCONFIGURED. Paired with the FC_IoMapper change that now drives DQ
        // unconditionally, so clearing these actually de-energises the output.
        "Valves_DB".Valve[#i].OpenValve := FALSE;
        "Valves_DB".Valve[#i].CloseValve := FALSE;
        "Valves_DB".CmdPos[#i] := 0;
        // Don't let an unconfigured/removed valve leave a stale latched alarm behind.
        "Valves_DB".TimeoutOpenAlarm[#i] := FALSE;
        "Valves_DB".TimeoutCloseAlarm[#i] := FALSE;
        "Valves_DB".UnexpMove[#i] := FALSE;
        "Valves_DB".DirFault[#i] := FALSE;
        "Valves_DB".PrevOpenFB[#i] := FALSE;
        "Valves_DB".PrevClosedFB[#i] := FALSE;
    END_IF;
END_FOR;

// ── 24 V field-supply group fault ────────────────────────────────────────────────
// Threshold guard, same reasoning as the timer zero guard: a 0 here would make
// "count >= threshold" permanently true and suppress every per-valve alarm on the ship.
#suppThr := "Valves_DB".SupplyFaultThreshold;
IF #suppThr <= 0 THEN #suppThr := 5; END_IF;

"Valves_DB".AftUnhealthyCnt := #tempAftUnh;
"Valves_DB".MidUnhealthyCnt := #tempMidUnh;
"Valves_DB".FwdUnhealthyCnt := #tempFwdUnh;

"Valves_DB".SupplyTmrAft(IN := (#tempAftUnh >= #suppThr), PT := T#2S);
"Valves_DB".SupplyTmrMid(IN := (#tempMidUnh >= #suppThr), PT := T#2S);
"Valves_DB".SupplyTmrFwd(IN := (#tempFwdUnh >= #suppThr), PT := T#2S);
"Valves_DB".AftSupplyFault := "Valves_DB".SupplyTmrAft.Q;
"Valves_DB".MidSupplyFault := "Valves_DB".SupplyTmrMid.Q;
"Valves_DB".FwdSupplyFault := "Valves_DB".SupplyTmrFwd.Q;

"Valves_DB".TotalOpen := #tempOpen;
"Valves_DB".TotalClosed := #tempClosed;
"Valves_DB".TotalTransit := #tempTransit;
"Valves_DB".TotalFault := #tempFault;
"Valves_DB".TotalLocal := #tempLocal;
"Valves_DB".TotalConfigured := #tempConfigured;

"Valves_DB".ErOpen := #tempErOpen;
"Valves_DB".ErClosed := #tempErClosed;
"Valves_DB".ErTransit := #tempErTransit;
"Valves_DB".ErFault := #tempErFault;
"Valves_DB".ErLocal := #tempErLocal;
"Valves_DB".ErConfigured := #tempErConfigured;

"Valves_DB".FwdOpen := #tempFwdOpen;
"Valves_DB".FwdClosed := #tempFwdClosed;
"Valves_DB".FwdTransit := #tempFwdTransit;
"Valves_DB".FwdFault := #tempFwdFault;
"Valves_DB".FwdLocal := #tempFwdLocal;
"Valves_DB".FwdConfigured := #tempFwdConfigured;

"Valves_DB".AftOpen := #tempAftOpen;
"Valves_DB".AftClosed := #tempAftClosed;
"Valves_DB".AftTransit := #tempAftTransit;
"Valves_DB".AftFault := #tempAftFault;
"Valves_DB".AftLocal := #tempAftLocal;
"Valves_DB".AftConfigured := #tempAftConfigured;

// ---- Alarm condition bit-packing -----------------------------------------
// WinCC discrete alarms trigger off a bit within a Word tag (RaisedStateTag +
// RaisedStateTagBitNumber), not a bare Bool array element, so each of the 7 per-valve
// conditions gets packed into 6 words (96 bits available, 89 used) here. Valve V's bit for any
// condition is word (V-1)/16, bit (V-1) MOD 16 — matches how the HMI-side alarm creation
// computes the same trigger address, so the two have to stay in lockstep.
FOR #w := 0 TO 5 DO
    #packWord := 0;
    FOR #b := 0 TO 15 DO
        #bitIdx := #w * 16 + #b + 1;
        IF #bitIdx <= 89 THEN
            #supp := (#bitIdx <= 27 AND "Valves_DB".AftSupplyFault)
                  OR (#bitIdx > 27 AND #bitIdx <= 54 AND "Valves_DB".MidSupplyFault)
                  OR (#bitIdx > 54 AND "Valves_DB".FwdSupplyFault);
            IF "Valves_DB".Valve[#bitIdx].Configured AND NOT "Valves_DB".Valve[#bitIdx].Healthy AND NOT #supp THEN
                #packWord := #packWord OR SHL(IN := W#16#1, N := INT_TO_UDINT(#b));
            END_IF;
        END_IF;
    END_FOR;
    "Valves_DB".W_Unhealthy[#w] := #packWord;
END_FOR;

FOR #w := 0 TO 5 DO
    #packWord := 0;
    FOR #b := 0 TO 15 DO
        #bitIdx := #w * 16 + #b + 1;
        IF #bitIdx <= 89 THEN
            IF "Valves_DB".Valve[#bitIdx].Configured AND "Valves_DB".Valve[#bitIdx].OpenFB AND "Valves_DB".Valve[#bitIdx].ClosedFB THEN
                #packWord := #packWord OR SHL(IN := W#16#1, N := INT_TO_UDINT(#b));
            END_IF;
        END_IF;
    END_FOR;
    "Valves_DB".W_Conflict[#w] := #packWord;
END_FOR;

FOR #w := 0 TO 5 DO
    #packWord := 0;
    FOR #b := 0 TO 15 DO
        #bitIdx := #w * 16 + #b + 1;
        IF #bitIdx <= 89 THEN
            IF "Valves_DB".Valve[#bitIdx].Configured AND "Valves_DB".TimeoutOpenAlarm[#bitIdx] THEN
                #packWord := #packWord OR SHL(IN := W#16#1, N := INT_TO_UDINT(#b));
            END_IF;
        END_IF;
    END_FOR;
    "Valves_DB".W_FailOpen[#w] := #packWord;
END_FOR;

FOR #w := 0 TO 5 DO
    #packWord := 0;
    FOR #b := 0 TO 15 DO
        #bitIdx := #w * 16 + #b + 1;
        IF #bitIdx <= 89 THEN
            IF "Valves_DB".Valve[#bitIdx].Configured AND "Valves_DB".TimeoutCloseAlarm[#bitIdx] THEN
                #packWord := #packWord OR SHL(IN := W#16#1, N := INT_TO_UDINT(#b));
            END_IF;
        END_IF;
    END_FOR;
    "Valves_DB".W_FailClose[#w] := #packWord;
END_FOR;

FOR #w := 0 TO 5 DO
    #packWord := 0;
    FOR #b := 0 TO 15 DO
        #bitIdx := #w * 16 + #b + 1;
        IF #bitIdx <= 89 THEN
            #supp := (#bitIdx <= 27 AND "Valves_DB".AftSupplyFault)
                  OR (#bitIdx > 27 AND #bitIdx <= 54 AND "Valves_DB".MidSupplyFault)
                  OR (#bitIdx > 54 AND "Valves_DB".FwdSupplyFault);
            IF "Valves_DB".Valve[#bitIdx].Configured AND "Valves_DB".PosLostTmr[#bitIdx].Q AND NOT #supp THEN
                #packWord := #packWord OR SHL(IN := W#16#1, N := INT_TO_UDINT(#b));
            END_IF;
        END_IF;
    END_FOR;
    "Valves_DB".W_LossPos[#w] := #packWord;
END_FOR;

FOR #w := 0 TO 5 DO
    #packWord := 0;
    FOR #b := 0 TO 15 DO
        #bitIdx := #w * 16 + #b + 1;
        IF #bitIdx <= 89 THEN
            #supp := (#bitIdx <= 27 AND "Valves_DB".AftSupplyFault)
                  OR (#bitIdx > 27 AND #bitIdx <= 54 AND "Valves_DB".MidSupplyFault)
                  OR (#bitIdx > 54 AND "Valves_DB".FwdSupplyFault);
            IF "Valves_DB".Valve[#bitIdx].Configured AND "Valves_DB".UnexpMove[#bitIdx] AND NOT #supp THEN
                #packWord := #packWord OR SHL(IN := W#16#1, N := INT_TO_UDINT(#b));
            END_IF;
        END_IF;
    END_FOR;
    "Valves_DB".W_UnexpMove[#w] := #packWord;
END_FOR;

FOR #w := 0 TO 5 DO
    #packWord := 0;
    FOR #b := 0 TO 15 DO
        #bitIdx := #w * 16 + #b + 1;
        IF #bitIdx <= 89 THEN
            IF "Valves_DB".Valve[#bitIdx].Configured AND "Valves_DB".Valve[#bitIdx].LocalMode THEN
                #packWord := #packWord OR SHL(IN := W#16#1, N := INT_TO_UDINT(#b));
            END_IF;
        END_IF;
    END_FOR;
    "Valves_DB".W_Local[#w] := #packWord;
END_FOR;

// H: direction / limit-switch discrepancy.
FOR #w := 0 TO 5 DO
    #packWord := 0;
    FOR #b := 0 TO 15 DO
        #bitIdx := #w * 16 + #b + 1;
        IF #bitIdx <= 89 THEN
            IF "Valves_DB".Valve[#bitIdx].Configured AND "Valves_DB".DirFault[#bitIdx] THEN
                #packWord := #packWord OR SHL(IN := W#16#1, N := INT_TO_UDINT(#b));
            END_IF;
        END_IF;
    END_FOR;
    "Valves_DB".W_DirFault[#w] := #packWord;
END_FOR;

// Simulated hardware health (indices 1..9) into a single word.
#packWord := 0;
FOR #b := 0 TO 8 DO
    IF NOT "Valves_DB".HwHealthy[#b + 1] THEN
        #packWord := #packWord OR SHL(IN := W#16#1, N := INT_TO_UDINT(#b));
    END_IF;
END_FOR;
"Valves_DB".HwWord := #packWord;

// ---- Paged table windows ------------------------------------------------
// The HMI valve table has 14 fixed slots. Copy whichever page each zone is showing into
// these windows so every HMI slot can bind to a constant tag name (e.g. ErTblState[3])
// rather than building the name in JavaScript from a page tag — that indirection is what
// forced the table onto ~126 polled scripts and made the screen slow to load.
// TblState = -1 marks a slot with no valve on this page (0 already means UNCONFIGURED).
// 14 iterations x 3 zones per scan is negligible next to the 89-valve loop above.

// ── PAGED TABLE WINDOWS — gated, not rebuilt every scan ────────────────────────────
// These four loops copy ~350 STRINGS per scan (tag, name, location, function, CmNo, VTag,
// state text x 58 slots). String copies are the slowest thing in this program and were the
// single biggest contributor to scan time, all to produce data no operator can read faster
// than a few times a second.
// So: rebuild on a 200 ms tick, OR immediately when a page changes. The page test matters -
// waiting up to 200 ms after a page button would feel laggy, and paging is the one moment the
// window contents change wholesale.
#doWindows := #winTick
    OR ("Valves_DB".AftPage <> "Valves_DB".PrevAftPage)
    OR ("Valves_DB".ErPage  <> "Valves_DB".PrevErPage)
    OR ("Valves_DB".FwdPage <> "Valves_DB".PrevFwdPage)
    OR ("Valves_DB".CfgPage <> "Valves_DB".PrevCfgPage);

IF #doWindows THEN
    "Valves_DB".PrevAftPage := "Valves_DB".AftPage;
    "Valves_DB".PrevErPage  := "Valves_DB".ErPage;
    "Valves_DB".PrevFwdPage := "Valves_DB".FwdPage;
    "Valves_DB".PrevCfgPage := "Valves_DB".CfgPage;

    // AFT BALLAST: valves 1..27 (2 pages)
    #base := 1 + "Valves_DB".AftPage * 14;
    FOR #j := 1 TO 14 DO
        #idx := #base + #j - 1;
        IF #idx <= 27 THEN
            "Valves_DB".AftTblState[#j] := "Valves_DB".StateCode[#idx];
            "Valves_DB".AftTblNo[#j] := #idx;
            // RIGHT() strips the leading sign-space INT_TO_STRING puts in front of a positive
            // number: without it CONCAT yields 'CM- 29' rather than 'CM-29'.
            IF #idx < 10 THEN
                "Valves_DB".AftTblTag[#j] := CONCAT(IN1 := 'CM-0', IN2 := RIGHT(IN := INT_TO_STRING(#idx), L := 1));
            ELSE
                "Valves_DB".AftTblTag[#j] := CONCAT(IN1 := 'CM-', IN2 := RIGHT(IN := INT_TO_STRING(#idx), L := 2));
            END_IF;
            "Valve_Meta_DB".AftTblName[#j] := "Valve_Meta_DB".Name[#idx];
            "Valve_Meta_DB".AftTblLoc[#j] := "Valve_Meta_DB".Location[#idx];
            "Valve_Meta_DB".AftTblFunc[#j] := "Valve_Meta_DB".FuncName[#idx];
            "Valve_Meta_DB".AftTblCmNo[#j] := "Valve_Meta_DB".CmNo[#idx];
            "Valve_Meta_DB".AftTblVTag[#j] := "Valve_Meta_DB".VTag[#idx];
            CASE "Valves_DB".StateCode[#idx] OF
                0: "Valves_DB".AftTblStateTxt[#j] := 'UNCONFIGURED';
                1: "Valves_DB".AftTblStateTxt[#j] := 'FAULT';
                2: "Valves_DB".AftTblStateTxt[#j] := 'LOCAL';
                3: "Valves_DB".AftTblStateTxt[#j] := 'OPEN';
                4: "Valves_DB".AftTblStateTxt[#j] := 'CLOSED';
                6: "Valves_DB".AftTblStateTxt[#j] := 'OPENING';
                7: "Valves_DB".AftTblStateTxt[#j] := 'CLOSING';
                // 'NO POSITION', not 'MOVING'. Code 5 means neither limit switch is made, which is
                // not the same as motion - 6 and 7 carry the genuine motion states now. Observed
                // live 2026-08-16: after Reset Fault on a failed travel the valve sits perfectly
                // still with no position for the 2s Loss-of-Position debounce, and the panel read
                // MOVING. That is the one moment the operator most needs the truth.
                ELSE "Valves_DB".AftTblStateTxt[#j] := 'NO POSITION';
            END_CASE;
        ELSE
            // 9, not 6: 6 became a real StateCode (OPENING) on 2026-08-16, and this
            // empty-slot sentinel shares the same value map on the HMI. Leaving it at 6 painted
            // every opening valve's status text transparent. 9 is outside the StateCode range.
            "Valves_DB".AftTblState[#j] := 9;
            "Valves_DB".AftTblNo[#j] := 0;
            "Valves_DB".AftTblTag[#j] := '';
            "Valves_DB".AftTblStateTxt[#j] := '';
            "Valve_Meta_DB".AftTblName[#j] := '';
            "Valve_Meta_DB".AftTblLoc[#j] := '';
            "Valve_Meta_DB".AftTblFunc[#j] := '';
            "Valve_Meta_DB".AftTblCmNo[#j] := '';
            "Valve_Meta_DB".AftTblVTag[#j] := '';
        END_IF;
    END_FOR;

    // BILGE / ER: valves 28..54 (2 pages)
    #base := 28 + "Valves_DB".ErPage * 14;
    FOR #j := 1 TO 14 DO
        #idx := #base + #j - 1;
        IF #idx <= 54 THEN
            "Valves_DB".ErTblState[#j] := "Valves_DB".StateCode[#idx];
            "Valves_DB".ErTblNo[#j] := #idx - 27;
            "Valves_DB".ErTblTag[#j] := CONCAT(IN1 := 'CM-', IN2 := RIGHT(IN := INT_TO_STRING(#idx), L := 2));
            "Valve_Meta_DB".ErTblName[#j] := "Valve_Meta_DB".Name[#idx];
            "Valve_Meta_DB".ErTblLoc[#j] := "Valve_Meta_DB".Location[#idx];
            "Valve_Meta_DB".ErTblFunc[#j] := "Valve_Meta_DB".FuncName[#idx];
            "Valve_Meta_DB".ErTblCmNo[#j] := "Valve_Meta_DB".CmNo[#idx];
            "Valve_Meta_DB".ErTblVTag[#j] := "Valve_Meta_DB".VTag[#idx];
            CASE "Valves_DB".StateCode[#idx] OF
                0: "Valves_DB".ErTblStateTxt[#j] := 'UNCONFIGURED';
                1: "Valves_DB".ErTblStateTxt[#j] := 'FAULT';
                2: "Valves_DB".ErTblStateTxt[#j] := 'LOCAL';
                3: "Valves_DB".ErTblStateTxt[#j] := 'OPEN';
                4: "Valves_DB".ErTblStateTxt[#j] := 'CLOSED';
                6: "Valves_DB".ErTblStateTxt[#j] := 'OPENING';
                7: "Valves_DB".ErTblStateTxt[#j] := 'CLOSING';
                ELSE "Valves_DB".ErTblStateTxt[#j] := 'NO POSITION';
            END_CASE;
        ELSE
            "Valves_DB".ErTblState[#j] := 9;   // empty slot — see AftTblState note above
            "Valves_DB".ErTblNo[#j] := 0;
            "Valves_DB".ErTblTag[#j] := '';
            "Valves_DB".ErTblStateTxt[#j] := '';
            "Valve_Meta_DB".ErTblName[#j] := '';
            "Valve_Meta_DB".ErTblLoc[#j] := '';
            "Valve_Meta_DB".ErTblFunc[#j] := '';
            "Valve_Meta_DB".ErTblCmNo[#j] := '';
            "Valve_Meta_DB".ErTblVTag[#j] := '';
        END_IF;
    END_FOR;

    // FORWARD BALLAST: valves 55..89 (3 pages of 14, 35 slots exactly - the widest zone, holding
    // the schedule's 35 FWD valves with no spare)
    #base := 55 + "Valves_DB".FwdPage * 14;
    FOR #j := 1 TO 14 DO
        #idx := #base + #j - 1;
        IF #idx <= 89 THEN
            "Valves_DB".FwdTblState[#j] := "Valves_DB".StateCode[#idx];
            "Valves_DB".FwdTblNo[#j] := #idx - 54;
            "Valves_DB".FwdTblTag[#j] := CONCAT(IN1 := 'CM-', IN2 := RIGHT(IN := INT_TO_STRING(#idx), L := 2));
            "Valve_Meta_DB".FwdTblName[#j] := "Valve_Meta_DB".Name[#idx];
            "Valve_Meta_DB".FwdTblLoc[#j] := "Valve_Meta_DB".Location[#idx];
            "Valve_Meta_DB".FwdTblFunc[#j] := "Valve_Meta_DB".FuncName[#idx];
            "Valve_Meta_DB".FwdTblCmNo[#j] := "Valve_Meta_DB".CmNo[#idx];
            "Valve_Meta_DB".FwdTblVTag[#j] := "Valve_Meta_DB".VTag[#idx];
            CASE "Valves_DB".StateCode[#idx] OF
                0: "Valves_DB".FwdTblStateTxt[#j] := 'UNCONFIGURED';
                1: "Valves_DB".FwdTblStateTxt[#j] := 'FAULT';
                2: "Valves_DB".FwdTblStateTxt[#j] := 'LOCAL';
                3: "Valves_DB".FwdTblStateTxt[#j] := 'OPEN';
                4: "Valves_DB".FwdTblStateTxt[#j] := 'CLOSED';
                6: "Valves_DB".FwdTblStateTxt[#j] := 'OPENING';
                7: "Valves_DB".FwdTblStateTxt[#j] := 'CLOSING';
                ELSE "Valves_DB".FwdTblStateTxt[#j] := 'NO POSITION';
            END_CASE;
        ELSE
            "Valves_DB".FwdTblState[#j] := 9;   // empty slot — see AftTblState note above
            "Valves_DB".FwdTblNo[#j] := 0;
            "Valves_DB".FwdTblTag[#j] := '';
            "Valves_DB".FwdTblStateTxt[#j] := '';
            "Valve_Meta_DB".FwdTblName[#j] := '';
            "Valve_Meta_DB".FwdTblLoc[#j] := '';
            "Valve_Meta_DB".FwdTblFunc[#j] := '';
            "Valve_Meta_DB".FwdTblCmNo[#j] := '';
            "Valve_Meta_DB".FwdTblVTag[#j] := '';
        END_IF;
    END_FOR;

    // CONFIGURATION SCREEN: all 89 slots in one global sequence (6 pages of 16, last one ragged
    // at 9), not zone-scoped like the three windows above - this screen shows the whole fleet,
    // so #idx IS the absolute valve number directly, no zone-start offset needed.
    #base := 1 + "Valves_DB".CfgPage * 16;
    FOR #j := 1 TO 16 DO
        #idx := #base + #j - 1;
        IF #idx <= 89 THEN
            "Valves_DB".CfgTblNo[#j] := #idx;
            IF #idx < 10 THEN
                "Valves_DB".CfgTblTag[#j] := CONCAT(IN1 := 'CM-0', IN2 := RIGHT(IN := INT_TO_STRING(#idx), L := 1));
            ELSE
                "Valves_DB".CfgTblTag[#j] := CONCAT(IN1 := 'CM-', IN2 := RIGHT(IN := INT_TO_STRING(#idx), L := 2));
            END_IF;
            IF #idx <= 27 THEN
                "Valves_DB".CfgTblZone[#j] := 'AFT BALLAST';
            ELSIF #idx <= 54 THEN
                "Valves_DB".CfgTblZone[#j] := 'BILGE-ER';
            ELSE
                "Valves_DB".CfgTblZone[#j] := 'BALLAST FWD';
            END_IF;
            "Valve_Meta_DB".CfgTblName[#j] := "Valve_Meta_DB".Name[#idx];
            "Valve_Meta_DB".CfgTblLoc[#j] := "Valve_Meta_DB".Location[#idx];
            // Client-schedule identity columns. Displayed verbatim - no fallback to the
            // computed CmNo/zone strings above, because a blank here is meaningful: it means
            // that valve has not been entered from the confirmed schedule yet, and showing a
            // derived 'CM-07' in its place would misrepresent unentered data as real.
            "Valve_Meta_DB".CfgTblCmNo[#j] := "Valve_Meta_DB".CmNo[#idx];
            "Valve_Meta_DB".CfgTblVTag[#j] := "Valve_Meta_DB".VTag[#idx];
            "Valve_Meta_DB".CfgTblSys[#j] := "Valve_Meta_DB".SysName[#idx];
            "Valve_Meta_DB".CfgTblFunc[#j] := "Valve_Meta_DB".FuncName[#idx];
            "Valves_DB".CfgTblConfigured[#j] := "Valves_DB".Valve[#idx].Configured;
            "Valves_DB".CfgTblState[#j] := "Valves_DB".StateCode[#idx];
            CASE "Valves_DB".StateCode[#idx] OF
                0: "Valves_DB".CfgTblStateTxt[#j] := 'UNCONFIGURED';
                1: "Valves_DB".CfgTblStateTxt[#j] := 'FAULT';
                2: "Valves_DB".CfgTblStateTxt[#j] := 'LOCAL';
                3: "Valves_DB".CfgTblStateTxt[#j] := 'OPEN';
                4: "Valves_DB".CfgTblStateTxt[#j] := 'CLOSED';
                6: "Valves_DB".CfgTblStateTxt[#j] := 'OPENING';
                7: "Valves_DB".CfgTblStateTxt[#j] := 'CLOSING';
                ELSE "Valves_DB".CfgTblStateTxt[#j] := 'NO POSITION';
            END_CASE;
        ELSE
            "Valves_DB".CfgTblNo[#j] := 0;
            "Valves_DB".CfgTblTag[#j] := '';
            "Valves_DB".CfgTblZone[#j] := '';
            "Valve_Meta_DB".CfgTblName[#j] := '';
            "Valve_Meta_DB".CfgTblLoc[#j] := '';
            "Valve_Meta_DB".CfgTblCmNo[#j] := '';
            "Valve_Meta_DB".CfgTblVTag[#j] := '';
            "Valve_Meta_DB".CfgTblSys[#j] := '';
            "Valve_Meta_DB".CfgTblFunc[#j] := '';
            "Valves_DB".CfgTblConfigured[#j] := FALSE;
            "Valves_DB".CfgTblState[#j] := 9;   // empty slot — see AftTblState note above
            "Valves_DB".CfgTblStateTxt[#j] := '';
        END_IF;
    END_FOR;
END_IF;


// SELECTED-VALVE MIRROR for the control popup - same trick as the three paged table windows
// above, applied to a window of exactly one valve. The HMI writes SelIdx when a valve badge is
// tapped; this copies that valve's live fields into fixed, non-indexed tags.
//
// Why: every popup field used to compute its own tag name at runtime ("V" + idx + "_State"),
// which WinCC cannot bind natively - so each one ran as a polled JavaScript at T500ms, ~14 of
// them, and the popup visibly lagged on open and on switching valves. Reading fixed tag names
// lets those same scripts run on AutomaticTags instead: evaluated when a value actually
// changes, not on a timer. Zero polling, instant update.
//
// Out-of-range (including SelIdx = 0 before any valve has ever been tapped) yields the
// unconfigured/blank state rather than stale data from whatever was selected last.
#sel := "Valves_DB".SelIdx;
IF #sel >= 1 AND #sel <= 89 THEN
    "Valves_DB".SelState      := "Valves_DB".StateCode[#sel];
    "Valves_DB".SelHealthy    := "Valves_DB".Valve[#sel].Healthy;
    "Valves_DB".SelLocalMode  := "Valves_DB".Valve[#sel].LocalMode;
    "Valves_DB".SelConfigured := "Valves_DB".Valve[#sel].Configured;
    "Valves_DB".SelDirFault   := "Valves_DB".DirFault[#sel];
    "Valves_DB".SelCmdPos     := "Valves_DB".CmdPos[#sel];
    "Valves_DB".SelPosCode    := "Valves_DB".PosCode[#sel];
    "Valves_DB".SelFaultCode  := "Valves_DB".FaultCode[#sel];
    "Valve_Meta_DB".SelCmNo   := "Valve_Meta_DB".CmNo[#sel];
    "Valve_Meta_DB".SelVTag   := "Valve_Meta_DB".VTag[#sel];
ELSE
    "Valves_DB".SelState      := 0;
    "Valves_DB".SelHealthy    := FALSE;
    "Valves_DB".SelLocalMode  := FALSE;
    "Valves_DB".SelConfigured := FALSE;
    "Valves_DB".SelDirFault   := FALSE;
    "Valves_DB".SelCmdPos     := 0;
    "Valves_DB".SelPosCode    := 0;
    "Valves_DB".SelFaultCode  := 0;
    "Valve_Meta_DB".SelCmNo   := '';
    "Valve_Meta_DB".SelVTag   := '';
END_IF;
